<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require_once dirname(__DIR__).'/app/Mail/ExternalMail.php';
use TNL\Mail\ExternalAccount;use TNL\Mail\ExternalMail;use TNL\Mail\ImapClient;use TNL\Mail\ReplyComposer;
header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: no-referrer');
header("Content-Security-Policy: default-src 'self'; style-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'");
tnl_session();$db=tnl_db();$as=($_GET['as']??'')==='admin'?'admin':(isset($_SESSION['employee_id'])?'employee':'admin');
$id=(int)($_SESSION[$as.'_id']??0);if($id<1){header('Location: '.($as==='admin'?'index.php':'employee.php'));exit;}
if($as==='employee'){$s=$db->prepare('SELECT credentials_version,must_change_password,can_send_external FROM users WHERE id=? AND active=1');$s->execute([$id]);$me=$s->fetch(PDO::FETCH_ASSOC);if(!$me||(int)$me['credentials_version']!==(int)($_SESSION['credentials_version']??0)){http_response_code(403);exit('Inicia sesión nuevamente.');}if($me['must_change_password']){header('Location: recovery.php');exit;}}
else{$s=$db->prepare('SELECT id FROM admins WHERE id=?');$s->execute([$id]);if(!$s->fetchColumn()){http_response_code(403);exit('Administrador inválido.');}}$s=null;
$canSend=$as==='admin'||!empty($me['can_send_external']);$owner=$as.':'.$id;$store=new ExternalAccount($db,dirname(__DIR__).'/storage');$error='';$notice=(string)($_SESSION['external_notice']??'');unset($_SESSION['external_notice']);$report=[];$account=null;$inbox=null;$message=null;
$self='external.php?as='.$as;
$draft=['to'=>'','subject'=>'','body'=>''];$activeThread=[];$composeMode='new';
try {
 $account=$store->load($owner);
 if($_SERVER['REQUEST_METHOD']==='POST'){
  tnl_check_csrf();$action=(string)($_POST['action']??'');
  if($action==='save'){$store->save($owner,$_POST,(string)($_POST['password']??''));unset($_SESSION['external_compose_tokens']);$_SESSION['external_notice']='Cuenta guardada. Pulsa Probar conexión antes de usarla.';header('Location: '.$self);exit;}
  elseif($action==='probe'){if(!$account)throw new RuntimeException('Configura primero la cuenta.');$report=ExternalMail::probe($account);}
  elseif($action==='send'){
   if(!$canSend)throw new RuntimeException('El administrador debe habilitar tu permiso de envío externo.');if(!$account)throw new RuntimeException('Configura primero la cuenta.');
   $draft=['to'=>(string)($_POST['to']??''),'subject'=>(string)($_POST['subject']??''),'body'=>(string)($_POST['body']??'')];$composeMode=in_array($_POST['compose_mode']??'',['reply','forward'],true)?$_POST['compose_mode']:'new';
   $nonce=(string)($_POST['send_nonce']??'');$context=$_SESSION['external_compose_tokens'][$nonce]??null;
   if(!$context||$context['owner']!==$owner||$context['email']!==$account['email']||time()-$context['created']>1800)throw new RuntimeException('Formulario de envío usado o caducado. Recarga la página.');unset($_SESSION['external_compose_tokens'][$nonce]);$activeThread=$context['thread'];
   $to=trim($draft['to']);$subject=trim($draft['subject']);$body=$draft['body'];$messageId=ExternalMail::send($account,$to,$subject,$body,null,$activeThread);
   try{$store->recordSent($owner,$to,$subject,$body,$messageId);$_SESSION['external_notice']='Servidor SMTP aceptó el mensaje. Esto no confirma su entrega final. La copia se guarda en TNL Mail.';}catch(Throwable $e){$_SESSION['external_notice']='SMTP aceptó el mensaje, pero no se pudo guardar la copia local. No lo reenvíes automáticamente.';}
   header('Location: '.$self.'&view=sent');exit;
  }else throw new RuntimeException('Acción inválida.');
 }
 if($_SERVER['REQUEST_METHOD']==='GET'&&$account&&($_GET['view']??'')==='compose'){
  if(!$canSend)throw new RuntimeException('El administrador debe habilitar tu permiso de envío externo.');$composeMode=(string)($_GET['mode']??'');if(!in_array($composeMode,['reply','forward'],true))throw new RuntimeException('Acción inválida.');
  $imap=new ImapClient($account);try{$imap->connect();$original=$imap->read((int)($_GET['uid']??0));$draft=ReplyComposer::prepare($original,$composeMode);$activeThread=$draft['thread'];}finally{$imap->close();}
 }
 if($account&&($_GET['view']??'')==='inbox'){$imap=new ImapClient($account);try{$imap->connect();if(isset($_GET['uid']))$message=$imap->read((int)$_GET['uid']);else $inbox=$imap->inbox((int)($_GET['page']??1));}finally{$imap->close();}}
}catch(Throwable $e){$error=$e->getMessage();}
$sendNonce=bin2hex(random_bytes(24));$_SESSION['external_compose_tokens']??=[];foreach($_SESSION['external_compose_tokens'] as $key=>$ctx)if(time()-$ctx['created']>1800)unset($_SESSION['external_compose_tokens'][$key]);while(count($_SESSION['external_compose_tokens'])>=20)array_shift($_SESSION['external_compose_tokens']);if($account)$_SESSION['external_compose_tokens'][$sendNonce]=['owner'=>$owner,'email'=>$account['email'],'created'=>time(),'thread'=>$activeThread];$sent=($_GET['view']??'')==='sent'?$store->sent($owner):[];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/app.css"><title>Correo externo · TNL Mail</title></head><body><div class="layout"><aside class="sidebar"><div class="brand">✉ TNL Mail</div><a class="nav" href="<?=$as==='admin'?'index.php':'employee.php'?>">Mi espacio</a><a class="nav" href="<?=tnl_escape($self)?>">Cuenta y redactar</a><a class="nav" href="<?=tnl_escape($self)?>&amp;view=inbox">Entrada IMAP</a><a class="nav" href="<?=tnl_escape($self)?>&amp;view=sent">Enviados en TNL Mail</a></aside><main class="main"><h1>Correo externo</h1><p>Conecta tu propio buzón. Su configuración y sus mensajes no se comparten con otros usuarios de TNL Mail.</p><?php if($error):?><p class="error"><?=tnl_escape($error)?></p><?php endif;?><?php if($notice):?><p><?=tnl_escape($notice)?></p><?php endif;?><?php foreach($report as $protocol=>$result):?><p><strong><?=tnl_escape(strtoupper($protocol))?>:</strong> <?=tnl_escape($result)?></p><?php endforeach;?>
<?php if($message):?><section class="panel"><h2><?=tnl_escape($message['headers']['subject']??'(sin asunto)')?></h2><p>De: <?=tnl_escape($message['headers']['from']??'')?></p><p><?=tnl_escape($message['headers']['date']??'')?></p><pre class="message-text"><?=tnl_escape($message['body'])?></pre><?php if($canSend):?><p><a href="<?=tnl_escape($self)?>&amp;view=compose&amp;mode=reply&amp;uid=<?=(int)$_GET['uid']?>">Responder</a> · <a href="<?=tnl_escape($self)?>&amp;view=compose&amp;mode=forward&amp;uid=<?=(int)$_GET['uid']?>">Reenviar</a></p><?php endif;?><a href="<?=tnl_escape($self)?>&amp;view=inbox">Volver a entrada</a></section>
<?php elseif($inbox!==null):?><section class="panel"><h2>Entrada · <?=$inbox['total']?> mensajes</h2><?php foreach($inbox['messages'] as $m):?><article class="card"><h3><a href="<?=tnl_escape($self)?>&amp;view=inbox&amp;uid=<?=$m['uid']?>"><?=tnl_escape($m['subject'])?></a></h3><p><?=tnl_escape($m['from'])?></p><small><?=tnl_escape($m['date'])?></small></article><?php endforeach;?><?php if(!$inbox['messages']):?><p>Bandeja vacía.</p><?php endif;?><?php if($inbox['page']>1):?><a href="<?=tnl_escape($self)?>&amp;view=inbox&amp;page=<?=$inbox['page']-1?>">Más recientes</a><?php endif;?><?php if($inbox['page']*20<$inbox['total']):?><a href="<?=tnl_escape($self)?>&amp;view=inbox&amp;page=<?=$inbox['page']+1?>">Más antiguos</a><?php endif;?></section>
<?php elseif(($_GET['view']??'')==='sent'):?><section class="panel"><h2>Últimos envíos desde TNL Mail</h2><p>Esta lista es local; no representa la carpeta Enviados del servidor IMAP.</p><?php foreach($sent as $m):?><article class="card"><h3><?=tnl_escape($m['subject'])?></h3><p><?=tnl_escape($m['recipient'])?> · <?=tnl_escape($m['created_at'])?></p></article><?php endforeach;?><?php if(!$sent):?><p>No hay envíos registrados.</p><?php endif;?></section>
<?php else:?><section class="panel"><h2>Conectar cuenta</h2><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="action" value="save"><label>Dirección y usuario SMTP/IMAP<input type="email" name="email" required value="<?=tnl_escape($account['email']??'')?>" autocomplete="username"></label><label>Servidor IMAP · SSL/TLS 993<input name="imap_host" required value="<?=tnl_escape($account['imap_host']??'premium902-2.web-hosting.com')?>"></label><label>Servidor SMTP · SSL/TLS 465<input name="smtp_host" required value="<?=tnl_escape($account['smtp_host']??'premium902-2.web-hosting.com')?>"></label><label>Contraseña del buzón<input type="password" name="password" autocomplete="new-password" <?=$account?'':'required'?>></label><small>Si ya está guardada, deja la contraseña vacía para conservarla. Se cifra en el servidor; no se vuelve a mostrar.</small><p><button>Guardar cuenta</button></p></form><?php if($account):?><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><button name="action" value="probe">Probar conexión sin enviar correo</button></form><?php endif;?></section>
<?php if($account&&!$canSend):?><p>El administrador debe habilitar tu permiso para enviar correo externo.</p><?php endif;?><?php if($account&&$canSend):?><section class="panel"><h2><?=tnl_escape(['new'=>'Redactar','reply'=>'Responder','forward'=>'Reenviar'][$composeMode]??'Redactar')?> desde <?=tnl_escape($account['email'])?></h2><?php if($composeMode==='forward'):?><p>Se reenvía el texto del mensaje. Los adjuntos todavía no se incluyen.</p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="action" value="send"><input type="hidden" name="send_nonce" value="<?=tnl_escape($sendNonce)?>"><input type="hidden" name="compose_mode" value="<?=tnl_escape($composeMode)?>"><label>Para<input type="email" name="to" required value="<?=tnl_escape($draft['to'])?>"></label><label>Asunto<input name="subject" maxlength="200" required value="<?=tnl_escape($draft['subject'])?>"></label><label>Mensaje<textarea name="body" rows="10" maxlength="50000" required><?=tnl_escape($draft['body'])?></textarea></label><button>Enviar correo</button></form></section><?php endif;?><?php endif;?><p><small>Primera versión: entrada y texto de mensajes de hasta 1 MB, sin adjuntos ni imágenes remotas. La lectura no marca mensajes como leídos. SSL/TLS obligatorio.</small></p></main></div></body></html>
